package android.view; public class MotionEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_MOVE=2,ACTION_CANCEL=3,ACTION_POINTER_DOWN=5,TOOL_TYPE_FINGER=1,TOOL_TYPE_STYLUS=2;public int action,count=1,pointer,tool=1;public float x,y;public long down,event;public boolean recycled;public float[][] history=new float[0][];public static int copies,recycles;public MotionEvent(int a,float x,float y,long d,long e){action=a;this.x=x;this.y=y;down=d;event=e;}public static MotionEvent obtain(MotionEvent s){MotionEvent m=new MotionEvent(s.action,s.x,s.y,s.down,s.event);m.count=s.count;m.pointer=s.pointer;m.tool=s.tool;copies++;return m;}public void setAction(int a){action=a;}public int getActionMasked(){return action;}public int getPointerCount(){return count;}public int getPointerId(int i){return pointer;}public int getToolType(int i){return tool;}public float getX(){return x;}public float getY(){return y;}public long getDownTime(){return down;}public long getEventTime(){return event;}public int getHistorySize(){return history.length;}public float getHistoricalX(int p,int h){return history[h][0];}public float getHistoricalY(int p,int h){return history[h][1];}public void recycle(){if(recycled)throw new AssertionError("double recycle");recycled=true;recycles++;}}

